const toast=document.getElementById('toast');
const dashboard=document.querySelector('.content');
const view=document.getElementById('demoView');
const views={
  Leads:{eyebrow:'LEAD MANAGEMENT',title:'Lead workspace',text:'Qualify new opportunities and turn conversations into clients.',action:'＋ Add lead',columns:[['New enquiries',['Aster & Co. — Brand identity','Nexon Studio — Website redesign','Solace Homes — Social media']],['Qualified',['Blue Shore Hotels — Campaign','Pine Labs — Product launch']],['Proposal ready',['Casa Botanica — Creative retainer','Vertex Finance — CRM setup']]]},
  'Sales pipeline':{eyebrow:'OPPORTUNITY MANAGEMENT',title:'Pipeline command center',text:'Track every deal from first enquiry to signed agreement.',action:'＋ Create opportunity',columns:[['Discovery',['8 opportunities','₹2.4L total value']],['Solution stage',['6 opportunities','₹3.1L total value']],['Proposal sent',['5 opportunities','₹5.6L total value']],['Closing',['3 opportunities','₹1.7L total value']]]},
  Clients:{eyebrow:'CLIENT RELATIONSHIPS',title:'Client 360°',text:'Every conversation, document and payment in one client record.',action:'＋ Add client',columns:[['Active clients',['Aster & Co. — ₹1,20,000','Casa Botanica — ₹2,40,000','Blue Shore Hotels — ₹3,10,000']],['Needs attention',['Pine Labs — Follow-up today','Nexon Studio — Proposal pending']],['Recently onboarded',['Solace Homes — 2 days ago','Vertex Finance — 5 days ago']]]},
  Projects:{eyebrow:'DELIVERY WORKSPACE',title:'Projects at a glance',text:'Keep delivery, approvals and budgets on track.',action:'＋ New project',columns:[['In progress',['Brand refresh — 68% complete','Website redesign — 44% complete','Campaign launch — 82% complete']],['Awaiting approval',['Product photography','Website content']],['Completed this month',['Retail identity system','SEO growth sprint']]]},
  Invoices:{eyebrow:'FINANCE OVERVIEW',title:'Invoices and payments',text:'Know what is paid, pending and due next.',action:'＋ Create invoice',columns:[['Outstanding',['INV-1042 · ₹82,000 · Due today','INV-1043 · ₹1,25,000 · Due 24 Sep']],['Paid this month',['INV-1037 · ₹96,000','INV-1039 · ₹2,40,000','INV-1040 · ₹1,10,000']],['Draft invoices',['Creative retainer · ₹75,000','Web project · ₹1,80,000']]]},
  Calendar:{eyebrow:'SCHEDULE',title:'Your week, in focus',text:'Meetings, follow-ups and key delivery dates in one calendar.',action:'＋ Add event',columns:[['Today',['10:30 — Discovery call','14:00 — Proposal review','16:30 — Payment follow-up']],['Tomorrow',['11:00 — Client onboarding','15:00 — Content approval']],['This week',['Website launch · Thursday','Monthly reporting · Friday']]]}
};
function showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2200)}
function renderView(name){if(name==='Dashboard'){dashboard.hidden=false;view.hidden=true;return}const item=views[name];dashboard.hidden=true;view.hidden=false;view.innerHTML=`<div class="demo-hero"><div><p class="eyebrow">${item.eyebrow}</p><h1>${item.title}</h1><p>${item.text}</p></div><button class="light demo-action">${item.action}</button></div><div class="demo-columns">${item.columns.map((column,index)=>`<article class="demo-column"><div class="column-head"><h2>${column[0]}</h2><span>${String(index+2).padStart(2,'0')}</span></div>${column[1].map((entry,n)=>`<button class="demo-record"><span class="record-mark">${['◉','◇','✦'][n%3]}</span><span>${entry}<small>Updated recently</small></span><b>›</b></button>`).join('')}</article>`).join('')}</div><section class="panel demo-insight"><div><p class="eyebrow">AI INSIGHT</p><h2>Ready for the next conversation</h2><p>OrbitFlow highlights priority actions and helps your team move faster with clear context.</p></div><button class="text-button">Ask AI Copilot →</button></section>`;view.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>showToast('Demo interaction complete')))}
document.querySelectorAll('.nav-item').forEach(item=>item.addEventListener('click',()=>{document.querySelector('.nav-item.active').classList.remove('active');item.classList.add('active');document.getElementById('crumb').textContent=item.dataset.view;renderView(item.dataset.view);showToast(`${item.dataset.view} opened`)}));
document.getElementById('newButton').addEventListener('click',()=>showToast('Create menu opened for the demo'));
document.getElementById('addLead').addEventListener('click',()=>showToast('New lead form opened for the demo'));
document.querySelectorAll('.focus-list button,.text-button,.tabs button').forEach(button=>button.addEventListener('click',()=>showToast('Demo interaction complete')));
document.getElementById('menuToggle').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
